enum integrity_status verify_hmac_xattr(struct dentry *dentry,
                                        const char *xattr_name,
                                        char *xattr_value,
                                        size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest = NULL;
    size_t digest_len = 0;
    int rc;

    if (iint->flags & INTEGRITY_IINT_HMAC)
        return iint->integrity_status;

    rc = get_xattr_data(dentry, xattr_name, &digest, &digest_len);
    if (rc < 0) {
        if (rc == -ENODATA)
            status = INTEGRITY_NO_ATTRIBUTE;
        else
            status = INTEGRITY_NOTVERIFIED;
        goto out;
    }

    if (is_hmac_digest(digest, digest_len)) {
        void *computed_digest = compute_hmac(dentry, xattr_value, xattr_value_len);
        if (!computed_digest) {
            status = INTEGRITY_NOTVERIFIED;
            goto out_free;
        }

        if (memcmp(digest, computed_digest, digest_len) == 0)
            status = INTEGRITY_PASS;
        else
            status = INTEGRITY_FAIL;
        kfree(computed_digest);
    } else {
        void *computed_hash = compute_hash(dentry, xattr_value, xattr_value_len);
        if (!computed_hash) {
            status = INTEGRITY_NOTVERIFIED;
            goto out_free;
        }

        if (memcmp(digest, computed_hash, digest_len) == 0)
            status = INTEGRITY_PASS;
        else
            status = INTEGRITY_FAIL;
        kfree(computed_hash);
    }

    iint->integrity_status = status;
    iint->flags |= INTEGRITY_IINT_HMAC;

out_free:
    kfree(digest);
out:
    return status;
}

enum integrity_status verify_hmac_for_xattr(struct dentry *dentry, const char *xattr_name,
                                            char *xattr_value, size_t xattr_value_len,
                                            struct integrity_iint_cache *iint) {
    enum integrity_status status;
    void *digest;
    size_t digest_len;
    int rc;

    if (iint->flags & INTEGRITY_PASS) {
        return INTEGRITY_PASS;
    }

    digest = kmalloc(xattr_value_len, GFP_KERNEL);
    if (!digest) {
        return INTEGRITY_NOTVERIFIED;
    }

    rc = security_get_xattr(dentry->d_inode, xattr_name, digest, xattr_value_len, 0);
    if (rc < 0) {
        kfree(digest);
        return INTEGRITY_NOTVERIFIED;
    }

    digest_len = rc;

    if (digest_len != xattr_value_len || memcmp(digest, xattr_value, xattr_value_len) != 0) {
        status = INTEGRITY_FAIL;
    } else {
        status = INTEGRITY_PASS;
    }

    kfree(digest);

    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest;
    size_t digest_len;
    int result;

    if (iint->flags & INTEGRITY_SIGNATURE_PRESENT)
        return INTEGRITY_STATUS_NO_CHANGE;

    digest = get_xattr_digest(dentry, xattr_name, &digest_len);
    if (!digest)
        return INTEGRITY_STATUS_NO_ATTRIBUTE;

    switch (xattr_value[0]) {
    case HMAC_TYPE_SHA256:
        result = verify_hmac_sha256(dentry, xattr_value, xattr_value_len, digest, digest_len);
        break;
    case HMAC_TYPE_SHA1:
        result = verify_hmac_sha1(dentry, xattr_value, xattr_value_len, digest, digest_len);
        break;
    default:
        result = -EINVAL;
        break;
    }

    kfree(digest);

    if (result < 0) {
        iint->flags |= INTEGRITY_SIGNATURE_INVALID;
        return INTEGRITY_STATUS_FAILURE;
    }

    return INTEGRITY_STATUS_SUCCESS;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status = INTEGRITY_PASS;
    void *digest;
    int rc;
    struct integrity_dentry_data *integrity_data = NULL;
    struct xattr_val xattr_val;
    size_t digest_len = 0;

    if (!xattr_name || !xattr_value || !xattr_value_len || !iint)
        return INTEGRITY_NA;

    if (iint->flags & INTEGRITY_IINT_CACHE_HMAC)
        return iint->status;

    rc = getxattr_value(dentry, xattr_name, &xattr_val);
    if (rc <= 0)
        return INTEGRITY_NA;

    digest = calculate_hmac_or_hash(xattr_val.data, xattr_val.len, &digest_len);
    if (!digest) {
        free_xattr_val(&xattr_val);
        return INTEGRITY_FAIL;
    }

    if (xattr_value_len != digest_len) {
        status = INTEGRITY_FAIL;
    } else if (memcmp(xattr_value, digest, digest_len) != 0) {
        status = INTEGRITY_FAIL;
    }

    iint->status = status;
    iint->flags |= INTEGRITY_IINT_CACHE_HMAC;

    free(digest);
    free_xattr_val(&xattr_val);
    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint) {
    enum integrity_status status = INTEGRITY_PASS;
    void *xattr_data = NULL;
    size_t xattr_data_len = 0;
    int ret;

    if (iint->flags & INTEGRITY_IINT_HMAC)
        return iint->integrity;

    xattr_data_len = vfs_getxattr(dentry, xattr_name, NULL, 0);
    if (xattr_data_len < 0)
        return INTEGRITY_NO_XATTR;

    xattr_data = kmalloc(xattr_data_len, GFP_KERNEL);
    if (!xattr_data) {
        status = INTEGRITY_FAIL;
        goto out;
    }

    ret = vfs_getxattr(dentry, xattr_name, xattr_data, xattr_data_len);
    if (ret < 0) {
        status = INTEGRITY_FAIL;
        goto out;
    }

    if (!xattr_data_len)
        return INTEGRITY_NO_XATTR;

    status = verify_hmac(xattr_value, xattr_value_len, xattr_data, xattr_data_len);
    if (status != INTEGRITY_PASS)
        iint->flags |= INTEGRITY_IINT_HMAC;

out:
    kfree(xattr_data);
    return status;
}
